def gen(rng):
    def fmt(a):
        return str(len(a)) + '\n' + ' '.join(map(str, a))
    tests = [fmt([0, 1, 0, 0, 1, 0, 1]), fmt([0]), fmt([1]), fmt([0, 1, 0]), fmt([0, 0, 0, 0]), fmt([1, 1, 1, 1]), fmt([1, 0, 0, 1]), fmt([0, 1, 0, 0, 1]),
             fmt([1, 0, 1, 0, 1, 0])]
    for n in (2, 3, 4, 6, 8, 10, 12, 14):
        for _ in range(3):
            p = rng.choice((0.2, 0.5, 0.8))
            tests.append(fmt([1 if rng.random() < p else 0 for _ in range(n)]))
    N = 100000
    tests.append(fmt([1] * N))
    tests.append(fmt([0] * N))
    tests.append(fmt([1] + [0] * (N - 2) + [1]))
    a = [0] * N
    for i in range(0, N, 300):
        a[i + rng.randint(0, 299) if i + 299 < N else i] = 1
    tests.append(fmt(a))
    tests.append(fmt([1 if rng.random() < 0.01 else 0 for _ in range(N)]))
    tests.append(fmt([1 if rng.random() < 0.5 else 0 for _ in range(N)]))
    return tests

